#pragma once
#include <TFT_eSPI.h>

// Screen text is Ukrainian, so it uses smooth (VLW) fonts with Cyrillic generated by
// tools/gen_vlw.py. FONT_BUILTIN unloads them so TFT_eSPI's numbered fonts work again
// (e.g. font 7 for big digits).
// FONT_TITLE: bold 30 px; FONT_CLOCK: bold 46 px, digits and ":" only.
enum UiFont { FONT_BUILTIN, FONT_SMALL, FONT_LARGE, FONT_TITLE, FONT_CLOCK };

void useFont(TFT_eSPI &tft, UiFont font);
